const config=window.RACHEL_CONFIG||{mode:'demo',apiBase:''};
const demo=config.mode==='demo', surface=document.querySelector('#surface');
let profile={},request=null,usedDomains=new Set(),usedEmails=new Set(),currentStage=1;
const escapeHTML=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function error(message){let el=document.querySelector('#error');if(!el){el=document.createElement('div');el.id='error';el.className='error';el.setAttribute('role','alert');surface.append(el);}el.textContent=message;}
function stage(n,label){currentStage=n;document.querySelector('#stage-label').textContent=label;document.querySelector('#step-count').textContent='0'+n+' / 03';for(let i=1;i<=3;i++)document.querySelector('#step'+i).classList.toggle('active',i===n);}
async function api(path,data){const response=await fetch(config.apiBase+path,{method:data?'POST':'GET',credentials:'same-origin',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});const result=await response.json();if(!response.ok)throw Error(result.error||'Service indisponible.');return result;}
document.querySelector('#mode').innerHTML=demo?'<strong>Démonstration privée</strong> Testez le parcours. Aucun email envoyé, aucune vidéo générée ou publiée.':'<strong>Une capsule offerte par entreprise</strong> Format journalistique · Publication automatique';
document.querySelector('#privacy-mode').textContent=demo?'Cette démonstration ne transmet pas vos saisies. Elles restent dans la page et sont effacées au rechargement. Les contrôles de doublons présentés ici sont simulés ; le moteur serveur les applique en base.':'Vos données sont traitées par Décisions & Co et ses prestataires techniques pour délivrer le service. La demande ne vous inscrit pas automatiquement à une newsletter.';
document.querySelector('#privacy').onclick=()=>document.querySelector('dialog').showModal();document.querySelector('#close-dialog').onclick=()=>document.querySelector('dialog').close();
function signup(){stage(1,'VOTRE ACCÈS');surface.innerHTML=`<h2>Faisons connaissance.</h2><p class="description">Recevez un lien personnel pour indiquer le site de votre entreprise.</p><form id="signup"><label>Prénom et nom<input name="name" autocomplete="name" required minlength="2" maxlength="100" placeholder="Camille Martin"></label><label>Société<input name="company" autocomplete="organization" required minlength="2" maxlength="150" placeholder="Votre entreprise"></label><label>Email professionnel<input name="email" type="email" autocomplete="email" required maxlength="254" placeholder="camille@entreprise.fr"></label><div id="captcha"></div><button class="primary">${demo?'Tester mon accès':'Recevoir mon lien d’accès'}</button><p class="fine">Votre email sert à vérifier votre accès et à recevoir votre capsule. Aucune inscription automatique à une newsletter.</p></form>`;
if(!demo&&config.turnstileSiteKey){const el=document.createElement('script');el.src='https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit';el.onload=()=>window.turnstile.render('#captcha',{sitekey:config.turnstileSiteKey});document.head.append(el);}
document.querySelector('#signup').onsubmit=async e=>{e.preventDefault();const fields=Object.fromEntries(new FormData(e.target));const button=e.target.querySelector('button');button.disabled=true;try{if(demo){profile=fields;if(usedEmails.has(fields.email.toLowerCase()))throw Error('Une démonstration a déjà été demandée avec cet email.');}else{fields.captcha=document.querySelector('[name="cf-turnstile-response"]')?.value||'';await api('/api/signup',fields);profile=fields;}verification();}catch(ex){error(ex.message);}finally{button.disabled=false;}};}
function verification(){surface.innerHTML=`<div class="mail-icon" aria-hidden="true">✉</div><h2>${demo?'Le lien d’accès, en situation.':'Consultez votre messagerie.'}</h2><p class="description">${demo?'En fonctionnement réel, un lien personnel valable 15 minutes serait envoyé à :':'Si l’adresse est valide, le lien personnel est envoyé à :'}</p><div class="success">${escapeHTML(profile.email)}</div><p class="description">${demo?'Le bouton ci-dessous simule le clic dans l’email. Il ne vérifie pas la propriété de cette adresse.':'Le lien permet d’accéder à votre espace. Vérifiez aussi le dossier des courriers indésirables.'}</p>${demo?'<button id="verify-demo" class="primary">Simuler la vérification de l’email</button>':''}<button id="back" class="secondary">Modifier mon adresse</button>`;if(demo)document.querySelector('#verify-demo').onclick=brief;document.querySelector('#back').onclick=signup;}
function brief(){stage(2,'VOTRE ENTREPRISE');surface.innerHTML=`<span class="pill">${demo?'Email vérifié · simulation':'Email vérifié'}</span><h2>Quel est votre site ?</h2><p class="description">Rachel s’appuie sur votre site public pour préparer une capsule factuelle sur ${escapeHTML(profile.company||'votre entreprise')}.</p><form id="brief"><label>Site de l’entreprise<input name="site" required placeholder="https://www.entreprise.fr" maxlength="300" inputmode="url"></label><label>SIREN <span class="fine">Facultatif · 9 chiffres</span><input name="siren" pattern="[0-9]{9}" maxlength="9" inputmode="numeric" placeholder="123456789"></label><p class="fine">L’email professionnel doit correspondre au domaine du site. Une seule démonstration est disponible par email et par domaine ; le SIREN permet de rapprocher plusieurs sites.</p><label class="checklabel"><input type="checkbox" name="acknowledged" required><span>J’ai compris que cette capsule sera publiée sur la chaîne YouTube Rachel, à partir d’informations publiques, sans validation préalable du script.</span></label><button class="primary">${demo?'Tester la création de ma capsule':'Créer ma capsule'}</button></form>`;document.querySelector('#brief').onsubmit=async e=>{e.preventDefault();const fields=Object.fromEntries(new FormData(e.target));const button=e.target.querySelector('button');button.disabled=true;try{if(demo){const u=new URL(fields.site.includes('://')?fields.site:'https://'+fields.site);const host=u.hostname.toLowerCase().replace(/^www\./,'').replace(/\.$/,'');if(!/^([a-z0-9-]+\.)+[a-z]{2,}$/.test(host)||u.username||u.password||!['https:','http:'].includes(u.protocol)||host.endsWith('.local'))throw Error('Indiquez le domaine public de votre entreprise.');const mailhost=profile.email.split('@')[1].toLowerCase();if(mailhost!==host&&!mailhost.endsWith('.'+host))throw Error('Utilisez un email professionnel correspondant au domaine du site.');if(usedDomains.has(host))throw Error('Une démonstration a déjà été demandée pour ce site.');usedDomains.add(host);usedEmails.add(profile.email.toLowerCase());request={domain:host,status:'demo'};result();}else{await api('/api/request',{...fields,acknowledged:true});await refresh();}}catch(ex){error(ex.message);}finally{button.disabled=false;}};}
const statuses=['queued','research','writing','voice','avatar','upload','processing','delivery','completed'];
function result(){stage(3,'VOTRE CAPSULE');const idx=statuses.indexOf(request.status);const complete=request.status==='completed';surface.innerHTML=`<span class="pill">${demo?'Parcours de démonstration':complete?'Capsule disponible':request.status==='blocked'?'Demande suspendue':'Demande enregistrée'}</span><h2>${demo?'Le parcours est prêt.':complete?'Votre entreprise à l’écran.':request.status==='blocked'?'Un contrôle est nécessaire.':'Rachel prépare votre capsule.'}</h2><p class="description">${escapeHTML(profile.company||'Votre entreprise')} · ${escapeHTML(request.domain)}</p>${demo?'<div class="preview-note">Le formulaire et le parcours ont été testés. Aucune analyse du site ni production vidéo n’a été effectuée. Le raccordement des fournisseurs permettra d’activer les étapes ci-dessous.</div>':''}<ol class="timeline">${['Recherche sur le site','Rédaction et vérification des faits','Voix et animation de Rachel','Contrôle : 30 secondes maximum','Publication YouTube et email'].map((name,i)=>{const threshold=[1,2,3,5,6][i];return `<li class="${!demo&&idx>threshold?'done':!demo&&idx===threshold?'current':''}"><b>${!demo&&idx>threshold?'✓':i+1}</b>${name}</li>`;}).join('')}</ol>${request.status==='blocked'?'<div class="error">'+escapeHTML(request.error||'Sources insuffisantes. La vidéo n’a pas été publiée.')+'</div>':''}${complete&&request.url?'<a class="primary" style="display:block;text-align:center" href="'+escapeHTML(request.url)+'" target="_blank" rel="noopener">Voir ma capsule sur YouTube</a>':''}${demo?'<button id="again" class="secondary">Tester une autre demande</button><p class="fine demo-action">Les contrôles serveur, la file de traitement et les adaptateurs Rachel sont fournis avec cette première version.</p>':!complete?'<button id="refresh" class="secondary">Actualiser l’avancement</button>':''}`;if(demo)document.querySelector('#again').onclick=signup;else if(!complete)document.querySelector('#refresh').onclick=refresh;}
async function refresh(){try{const data=await api('/api/me');profile=data;request=data.request;if(request)result();else brief();}catch(ex){error(ex.message);}}
async function start(){signup();const token=new URL(location.href).searchParams.get('verify');if(token&&!demo){history.replaceState(null,'','/');surface.innerHTML='<h2>Votre accès personnel</h2><p class="description">Confirmez l’ouverture du lien reçu par email.</p><button id="open-link" class="primary">Accéder à mon espace</button>';document.querySelector('#open-link').onclick=async()=>{try{await api('/api/verify',{token});await refresh();}catch(ex){error(ex.message);}};}else if(!demo){try{const data=await api('/api/me');profile=data;request=data.request;if(request)result();else brief();}catch{}}}
start();
if(document.modelContext?.registerTool){Promise.resolve(document.modelContext.registerTool({name:'read_capsule_journey',title:'Lire l’état du parcours',description:'Lire l’étape affichée et le statut de la capsule, sans créer de demande.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({mode:config.mode,stage:currentStage,status:request?.status||'not_requested'})})).catch(()=>{});}
